  {
   "cell_type": "code",
   "execution_count": null,
   "metadata": {},
   "outputs": [],
   "source": [
    "# ============================================================\n",
    "# EVALUACIÓN TEST - YOLOv8 (15 checkpoints)\n",
    "# ============================================================\n",
    "\n",
    "!pip install -q ultralytics\n",
    "\n",
    "from ultralytics import YOLO\n",
    "from pathlib import Path\n",
    "import pandas as pd\n",
    "import numpy as np\n",
    "import re\n",
    "import os\n",
    "import torch\n",
    "\n",
    "WEIGHTS_DIR = \"/content/ENTRENAMIENTOS_PT_VF\"\n",
    "DATA_YAML   = \"/content/dataset/data.yaml\"\n",
    "OUTPUT_DIR  = \"/content/test_evaluation\"\n",
    "\n",
    "os.makedirs(OUTPUT_DIR, exist_ok=True)\n",
    "\n",
    "# Buscar los 15 checkpoints YOLOv8\n",
    "v8_weights = sorted(\n",
    "    Path(WEIGHTS_DIR).rglob(\"best_v8*.pt\"),\n",
    "    key=lambda x: (\n",
    "        re.search(r'best_(v8[nsm])_(\\d+)', x.stem).group(1),\n",
    "        int(re.search(r'best_(v8[nsm])_(\\d+)', x.stem).group(2))\n",
    "    )\n",
    ")\n",
    "\n",
    "print(f\"YOLOv8 checkpoints encontrados: {len(v8_weights)}\")\n",
    "\n",
    "assert len(v8_weights) == 15, \\\n",
    "    f\"ERROR: se esperaban 15 pesos YOLOv8 y se encontraron {len(v8_weights)}\"\n",
    "\n",
    "rows = []\n",
    "\n",
    "for i, weight in enumerate(v8_weights, 1):\n",
    "\n",
    "    match = re.search(r'best_(v8[nsm])_(\\d+)', weight.stem)\n",
    "    model_name = match.group(1)\n",
    "    run = int(match.group(2))\n",
    "\n",
    "    print(\"\\n\" + \"=\"*70)\n",
    "    print(f\"[{i}/15] Evaluando {model_name} - Run {run}\")\n",
    "    print(f\"Peso: {weight}\")\n",
    "    print(\"=\"*70)\n",
    "\n",
    "    model = YOLO(str(weight))\n",
    "\n",
    "    metrics = model.val(\n",
    "        data=DATA_YAML,\n",
    "        split=\"test\",\n",
    "        imgsz=640,\n",
    "        batch=1,\n",
    "        conf=0.001,\n",
    "        iou=0.60,\n",
    "        device=\"cuda:0\" if torch.cuda.is_available() else \"cpu\",\n",
    "        plots=False,\n",
    "        save_json=False,\n",
    "        verbose=False,\n",
    "        project=OUTPUT_DIR,\n",
    "        name=f\"{model_name}_run{run}\"\n",
    "    )\n",
    "\n",
    "    # Métricas globales\n",
    "    precision = float(metrics.box.mp)\n",
    "    recall = float(metrics.box.mr)\n",
    "    map50 = float(metrics.box.map50)\n",
    "    map5095 = float(metrics.box.map)\n",
    "\n",
    "    # AP50-95 por clase\n",
    "    ap_class = np.asarray(metrics.box.maps, dtype=float)\n",
    "\n",
    "    row = {\n",
    "        \"Model\": model_name,\n",
    "        \"Run\": run,\n",
    "        \"Precision\": precision,\n",
    "        \"Recall\": recall,\n",
    "        \"mAP50\": map50,\n",
    "        \"mAP50-95\": map5095,\n",
    "    }\n",
    "\n",
    "    # Obtener nombres reales de las clases\n",
    "    names = metrics.names\n",
    "\n",
    "    for class_id, ap in enumerate(ap_class):\n",
    "        class_name = names[class_id]\n",
    "        row[f\"AP50-95_{class_name}\"] = float(ap)\n",
    "\n",
    "    rows.append(row)\n",
    "\n",
    "# ============================================================\n",
    "# GUARDAR RESULTADOS\n",
    "# ============================================================\n",
    "\n",
    "df_v8 = pd.DataFrame(rows).sort_values([\"Model\", \"Run\"])\n",
    "\n",
    "csv_path = \"/content/YOLOv8_TEST_RESULTS.csv\"\n",
    "df_v8.to_csv(csv_path, index=False)\n",
    "\n",
    "print(\"\\n\" + \"=\"*70)\n",
    "print(\"EVALUACIÓN YOLOv8 TERMINADA\")\n",
    "print(\"=\"*70)\n",
    "\n",
    "display(df_v8)\n",
    "\n",
    "print(f\"\\nResultados guardados en:\\n{csv_path}\")"
   ]
  },
