    "    yerr=v5_sd,\n",
    "    capsize=4,\n",
    "    label=\"YOLOv5\"\n",
    ")\n",
    "\n",
    "bars_v8 = ax.bar(\n",
    "    x + width/2,\n",
    "    v8_mean,\n",
    "    width,\n",
    "    yerr=v8_sd,\n",
    "    capsize=4,\n",
    "    label=\"YOLOv8\"\n",
