    "ax.set_ylabel(\"mAP@0.5:0.95\", fontsize=11)\n",
    "\n",
    "ax.set_xticks(x)\n",
    "ax.set_xticklabels(scales)\n",
    "\n",
    "# Start at zero to avoid visually exaggerating differences\n",
    "ax.set_ylim(0, 0.70)\n",
    "\n",
    "ax.grid(\n",
    "    axis=\"y\",\n",
    "    linestyle=\"--\",\n",
    "    alpha=0.3\n",
    ")\n",
    "\n",
    "ax.set_axisbelow(True)\n",
    "ax.legend(frameon=False)\n",
    "\n",
    "ax.tick_params(axis=\"both\", labelsize=10)\n",
    "\n",
    "# ============================================================\n",
    "# VALUE LABELS\n",
    "# ============================================================\n",
    "\n",
    "for bars in [bars_v5, bars_v8]:\n",
    "    for bar in bars:\n",
    "        height = bar.get_height()\n",
    "\n",
    "        ax.text(\n",
