    "v8s = [RUN1, RUN2, RUN3, RUN4, RUN5]\n",
    "\n",
    "v5m = [RUN1, RUN2, RUN3, RUN4, RUN5]\n",
    "v8m = [RUN1, RUN2, RUN3, RUN4, RUN5]\n",
    "\n",
    "comparisons = {\n",
    "    \"Nano\": (v5n, v8n),\n",
    "    \"Small\": (v5s, v8s),\n",
    "    \"Medium\": (v5m, v8m)\n",
    "}\n",
    "\n",
    "for scale, (v5, v8) in comparisons.items():\n",
    "    r = hedges_g(v5, v8)\n",
    "\n",
    "    print(f\"\\n{scale}\")\n",
    "    print(f\"YOLOv5 = {r['mean_v5']:.4f} ± {r['sd_v5']:.4f}\")\n",
    "    print(f\"YOLOv8 = {r['mean_v8']:.4f} ± {r['sd_v8']:.4f}\")\n",
