    "import numpy as np\n",
    "import matplotlib.pyplot as plt\n",
    "\n",
    "# ============================================================\n",
    "# DATA\n",
    "# ============================================================\n",
    "\n",
    "models = [\n",
    "    \"YOLOv5n\", \"YOLOv5s\", \"YOLOv5m\",\n",
    "    \"YOLOv8n\", \"YOLOv8s\", \"YOLOv8m\"\n",
    "]\n",
    "\n",
    "# Final TEST mAP@0.5:0.95\n",
    "map5095 = np.array([\n",
    "    0.5487,\n",
    "    0.6016,\n",
    "    0.6104,\n",
    "    0.6177,\n",
    "    0.6345,\n",
    "    0.6391\n",
    "])\n",
    "\n",
    "# Final CPU benchmark latency (ms)\n",
    "latency = np.array([\n",
    "    54.211337,\n",
    "    112.742963,\n",
    "    260.655070,   # corrected YOLOv5m rerun\n",
    "    50.945706,\n",
    "    138.598078,\n",
    "    361.437564    # corrected YOLOv8m rerun\n",
    "])\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# PARETO FRONT\n",
    "# Lower latency = better\n",
    "# Higher mAP = better\n",
    "# ============================================================\n",
    "\n",
    "pareto = []\n",
    "\n",
    "for i in range(len(models)):\n",
    "    dominated = False\n",
    "\n",
    "    for j in range(len(models)):\n",
    "        if i == j:\n",
    "            continue\n",
    "\n",
    "        # j dominates i if:\n",
    "        # latency_j <= latency_i\n",
    "        # mAP_j >= mAP_i\n",
    "        # and at least one is strictly better\n",
    "        if (\n",
    "            latency[j] <= latency[i]\n",
    "            and map5095[j] >= map5095[i]\n",
    "            and (\n",
    "                latency[j] < latency[i]\n",
    "                or map5095[j] > map5095[i]\n",
    "            )\n",
    "        ):\n",
    "            dominated = True\n",
    "            break\n",
    "\n",
    "    if not dominated:\n",
    "        pareto.append(i)\n",
    "\n",
    "\n",
    "# Sort Pareto points by latency\n",
    "pareto = sorted(pareto, key=lambda i: latency[i])\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# PLOT\n",
    "# ============================================================\n",
    "\n",
    "fig, ax = plt.subplots(figsize=(8, 5.5))\n",
    "\n",
    "# All models\n",
    "ax.scatter(\n",
    "    latency,\n",
    "    map5095,\n",
    "    s=75,\n",
    "    zorder=3\n",
    ")\n",
    "\n",
    "# Model labels\n",
    "offsets = {\n",
    "    \"YOLOv5n\": (8, -15),\n",
    "    \"YOLOv5s\": (8, -12),\n",
    "    \"YOLOv5m\": (8, -12),\n",
    "    \"YOLOv8n\": (8, 8),\n",
    "    \"YOLOv8s\": (8, 8),\n",
    "    \"YOLOv8m\": (8, 8)\n",
    "}\n",
    "\n",
    "for i, model in enumerate(models):\n",
    "    dx, dy = offsets[model]\n",
    "\n",
    "    ax.annotate(\n",
    "        model,\n",
    "        (latency[i], map5095[i]),\n",
    "        xytext=(dx, dy),\n",
    "        textcoords=\"offset points\",\n",
    "        fontsize=10\n",
    "    )\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# PARETO FRONT LINE\n",
    "# ============================================================\n",
    "\n",
    "pareto_latency = [latency[i] for i in pareto]\n",
    "pareto_map = [map5095[i] for i in pareto]\n",
    "\n",
    "ax.plot(\n",
    "    pareto_latency,\n",
    "    pareto_map,\n",
    "    linestyle=\"--\",\n",
    "    linewidth=1.5,\n",
    "    label=\"Pareto front\",\n",
    "    zorder=2\n",
    ")\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# FORMATTING\n",
    "# ============================================================\n",
    "\n",
    "ax.set_xlabel(\"CPU Inference Latency (ms)\", fontsize=11)\n",
    "ax.set_ylabel(\"Test mAP@0.5:0.95\", fontsize=11)\n",
    "\n",
    "ax.grid(\n",
    "    True,\n",
    "    linestyle=\"--\",\n",
    "    alpha=0.3\n",
    ")\n",
    "\n",
    "ax.legend(frameon=False)\n",
    "\n",
    "plt.tight_layout()\n",
    "\n",
    "# High-resolution figure for paper\n",
    "plt.savefig(\n",
    "    \"performance_latency_pareto.png\",\n",
    "    dpi=600,\n",
    "    bbox_inches=\"tight\"\n",
    ")\n",
    "\n",
    "plt.show()\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# PRINT PARETO MODELS\n",
    "# ============================================================\n",
    "\n",
    "print(\"Models on Pareto front:\")\n",
    "for i in pareto:\n",
    "    print(\n",
    "        f\"{models[i]}: \"\n",
    "        f\"{latency[i]:.2f} ms, \"\n",
    "        f\"mAP@0.5:0.95 = {map5095[i]:.4f}\"\n",
    "    )"
