    "    recursive=True\n",
    ")\n",
    "\n",
    "if len(matches) == 0:\n",
    "    raise FileNotFoundError(\n",
    "        \"No se encontró best_v5m_4.pt dentro de /content/\"\n",
    "    )\n",
    "\n",
    "if len(matches) > 1:\n",
    "    print(\"⚠️ Se encontraron varios pesos:\")\n",
    "    for m in matches:\n",
    "        print(m)\n",
    "    print(\"\\nSe utilizará el primero.\")\n",
    "\n",
    "WEIGHT_V5 = matches[0]\n",
    "\n",
    "print(\"=\" * 70)\n",
    "print(\"PESO YOLOv5m RUN 4\")\n",
    "print(\"=\" * 70)\n",
    "print(WEIGHT_V5)\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 2. RUTAS\n",
    "# ============================================================\n",
    "\n",
    "YOLOV5_DIR = \"/content/yolov5\"\n",
    "DATA_YAML = \"/content/data_v5_test.yaml\"\n",
    "\n",
    "OUTPUT_DIR = \"/content/confusion_matrices\"\n",
    "RUN_NAME = \"YOLOv5m_Run4_conf025\"\n",
    "\n",
    "SAVE_DIR = os.path.join(\n",
    "    OUTPUT_DIR,\n",
    "    RUN_NAME\n",
    ")\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 3. VERIFICACIONES\n",
    "# ============================================================\n",
    "\n",
    "if not os.path.exists(YOLOV5_DIR):\n",
    "    raise FileNotFoundError(\n",
    "        \"No se encontró /content/yolov5\"\n",
    "    )\n",
    "\n",
    "if not os.path.exists(DATA_YAML):\n",
    "    raise FileNotFoundError(\n",
    "        \"No se encontró /content/data_v5_test.yaml\"\n",
    "    )\n",
    "\n",
    "print(\"\\nDataset:\")\n",
