    "# ============================================================\n",
    "# YOLOv8m RUN 4\n",
    "# GRAD-CAM - LAYER 15\n",
    "# VERIFICATION ON SAME 8 TEST IMAGES\n",
    "# ============================================================\n",
    "\n",
    "import os\n",
    "import cv2\n",
    "import torch\n",
    "import numpy as np\n",
    "import matplotlib.pyplot as plt\n",
    "\n",
    "from pytorch_grad_cam import GradCAM\n",
    "from pytorch_grad_cam.utils.image import show_cam_on_image\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 1. CONFIGURATION\n",
    "# ============================================================\n",
    "\n",
    "OUTPUT_DIR_L15 = \"/content/gradcam_v8m_layer15\"\n",
    "\n",
    "os.makedirs(\n",
    "    OUTPUT_DIR_L15,\n",
    "    exist_ok=True\n",
    ")\n",
    "\n",
    "# Enable gradients globally\n",
    "torch.set_grad_enabled(True)\n",
    "\n",
    "# Enable gradients for all model parameters\n",
    "for param in model.parameters():\n",
    "    param.requires_grad_(True)\n",
    "\n",
    "model.eval()\n",
    "wrapped_model.eval()\n",
    "\n",
    "# Layer selected after layer-comparison experiment\n",
    "TARGET_LAYER = model.model[15].cv2.conv\n",
    "\n",
    "# Class names\n",
    "CLASS_NAMES = yolo.names\n",
    "\n",
    "\n",
    "print(\"=\" * 70)\n",
    "print(\"YOLOv8m RUN 4 - GRAD-CAM LAYER 15\")\n",
    "print(\"=\" * 70)\n",
    "\n",
    "print(\"\\nTarget layer:\")\n",
    "print(TARGET_LAYER)\n",
    "\n",
    "print(\"\\nImages to analyze:\")\n",
    "print(len(selected_images))\n",
    "\n",
    "print(\"\\nClasses:\")\n",
    "print(CLASS_NAMES)\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 2. INITIALIZE GRAD-CAM\n",
    "# ============================================================\n",
    "\n",
    "cam = GradCAM(\n",
    "    model=wrapped_model,\n",
    "    target_layers=[TARGET_LAYER]\n",
    ")\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 3. STORAGE\n",
    "# ============================================================\n",
    "\n",
    "generated_layer15 = []\n",
    "\n",
    "# Raw results used later for final Fig. 6\n",
    "gradcam_v8_results = []\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 4. PROCESS SAME 8 TEST IMAGES\n",
    "# ============================================================\n",
    "\n",
    "for number, image_path in enumerate(\n",
    "    selected_images,\n",
    "    start=1\n",
    "):\n",
    "\n",
    "    print(\"\\n\" + \"-\" * 70)\n",
    "\n",
    "    print(\n",
    "        f\"[{number}/{len(selected_images)}] \"\n",
    "        f\"{os.path.basename(image_path)}\"\n",
    "    )\n",
    "\n",
    "\n",
    "    # --------------------------------------------------------\n",
    "    # A. STANDARD YOLOv8 DETECTION\n",
    "    # --------------------------------------------------------\n",
    "\n",
    "    results = yolo.predict(\n",
    "        source=image_path,\n",
    "        imgsz=640,\n",
    "        conf=0.25,\n",
    "        iou=0.60,\n",
    "        verbose=False\n",
    "    )\n",
    "\n",
    "    result = results[0]\n",
    "\n",
    "    if (\n",
    "        result.boxes is None\n",
    "        or len(result.boxes) == 0\n",
    "    ):\n",
    "\n",
    "        print(\n",
    "            \"No detection found - skipped.\"\n",
    "        )\n",
    "\n",
    "        continue\n",
    "\n",
    "\n",
    "    # --------------------------------------------------------\n",
    "    # B. HIGHEST-CONFIDENCE DETECTION\n",
    "    # --------------------------------------------------------\n",
    "\n",
    "    confidences = (\n",
    "        result.boxes.conf\n",
    "        .detach()\n",
    "        .cpu()\n",
    "        .numpy()\n",
    "    )\n",
    "\n",
    "    best_index = int(\n",
    "        np.argmax(confidences)\n",
    "    )\n",
    "\n",
    "    best_box = result.boxes[\n",
    "        best_index\n",
    "    ]\n",
    "\n",
    "    class_id = int(\n",
    "        best_box.cls.item()\n",
    "    )\n",
    "\n",
    "    confidence = float(\n",
    "        best_box.conf.item()\n",
    "    )\n",
    "\n",
    "    class_name = CLASS_NAMES[\n",
    "        class_id\n",
    "    ]\n",
    "\n",
    "\n",
    "    print(\n",
    "        f\"Selected detection: \"\n",
    "        f\"{class_name} | \"\n",
    "        f\"confidence={confidence:.3f}\"\n",
    "    )\n",
    "\n",
    "\n",
    "    # --------------------------------------------------------\n",
    "    # C. PREPARE IMAGE\n",
    "    # --------------------------------------------------------\n",
    "\n",
    "    (\n",
    "        original_rgb,\n",
    "        input_rgb,\n",
    "        input_tensor,\n",
    "        ratio,\n",
    "        padding\n",
    "    ) = prepare_image(\n",
    "        image_path\n",
    "    )\n",
    "\n",
    "\n",
    "    # --------------------------------------------------------\n",
    "    # IMPORTANT:\n",
    "    # Enable gradient tracking for Grad-CAM\n",
    "    # --------------------------------------------------------\n",
    "\n",
    "    input_tensor = (\n",
    "        input_tensor\n",
    "        .clone()\n",
    "        .detach()\n",
    "        .requires_grad_(True)\n",
    "    )\n",
    "\n",
    "\n",
    "    # --------------------------------------------------------\n",
    "    # D. CLASS-CONDITIONED TARGET\n",
    "    # --------------------------------------------------------\n",
    "\n",
    "    targets = [\n",
    "        YOLOClassDetectionTarget(\n",
    "            class_id\n",
    "        )\n",
    "    ]\n",
    "\n",
    "\n",
    "    # Clear previous gradients\n",
    "    wrapped_model.zero_grad(\n",
    "        set_to_none=True\n",
    "    )\n",
    "\n",
    "\n",
    "    # --------------------------------------------------------\n",
    "    # E. GRAD-CAM\n",
    "    # --------------------------------------------------------\n",
    "\n",
    "    with torch.enable_grad():\n",
    "\n",
    "        grayscale_cam = cam(\n",
    "            input_tensor=input_tensor,\n",
    "            targets=targets\n",
    "        )[0]\n",
    "\n",
    "\n",
    "    # --------------------------------------------------------\n",
    "    # F. CREATE OVERLAY\n",
    "    # --------------------------------------------------------\n",
    "\n",
    "    cam_overlay = show_cam_on_image(\n",
    "        input_rgb,\n",
    "        grayscale_cam,\n",
    "        use_rgb=True\n",
    "    )\n",
    "\n",
    "\n",
    "    # --------------------------------------------------------\n",
    "    # G. STORE RAW RESULT\n",
    "    # FOR FINAL IJACSA FIG. 6\n",
    "    # --------------------------------------------------------\n",
    "\n",
    "    gradcam_v8_results.append(\n",
    "        {\n",
    "            \"number\": number,\n",
    "            \"image_path\": image_path,\n",
    "\n",
    "            \"original\":\n",
    "                original_rgb.copy(),\n",
    "\n",
    "            \"gradcam\":\n",
    "                cam_overlay.copy(),\n",
    "\n",
    "            \"class_id\":\n",
    "                class_id,\n",
    "\n",
    "            \"class_name\":\n",
    "                class_name,\n",
    "\n",
    "            \"confidence\":\n",
    "                confidence\n",
    "        }\n",
    "    )\n",
    "\n",
    "\n",
    "    # --------------------------------------------------------\n",
    "    # H. SAVE INDIVIDUAL GRAD-CAM\n",
    "    # --------------------------------------------------------\n",
    "\n",
    "    base_name = os.path.splitext(\n",
    "        os.path.basename(\n",
    "            image_path\n",
    "        )\n",
    "    )[0]\n",
    "\n",
    "\n",
    "    cam_path = os.path.join(\n",
    "        OUTPUT_DIR_L15,\n",
    "\n",
    "        f\"{number:02d}_\"\n",
    "        f\"{base_name}_\"\n",
    "        f\"{class_name}_\"\n",
    "        f\"L15_gradcam.png\"\n",
    "    )\n",
    "\n",
    "\n",
    "    cv2.imwrite(\n",
    "        cam_path,\n",
    "\n",
    "        cv2.cvtColor(\n",
    "            cam_overlay,\n",
    "            cv2.COLOR_RGB2BGR\n",
    "        )\n",
    "    )\n",
    "\n",
    "\n",
    "    # --------------------------------------------------------\n",
    "    # I. ORIGINAL + GRAD-CAM\n",
    "    # VERIFICATION ONLY\n",
    "    # --------------------------------------------------------\n",
    "\n",
    "    fig, axes = plt.subplots(\n",
    "        1,\n",
    "        2,\n",
    "        figsize=(10, 5)\n",
    "    )\n",
    "\n",
    "\n",
    "    axes[0].imshow(\n",
    "        original_rgb\n",
    "    )\n",
    "\n",
    "    axes[0].set_title(\n",
    "        \"Original\"\n",
    "    )\n",
    "\n",
    "    axes[0].axis(\n",
    "        \"off\"\n",
    "    )\n",
    "\n",
    "\n",
    "    axes[1].imshow(\n",
    "        cam_overlay\n",
    "    )\n",
    "\n",
    "    axes[1].set_title(\n",
    "        f\"Grad-CAM - Layer 15\\n\"\n",
    "        f\"Target: \"\n",
    "        f\"{class_name} \"\n",
    "        f\"({confidence:.2f})\"\n",
    "    )\n",
    "\n",
    "    axes[1].axis(\n",
    "        \"off\"\n",
    "    )\n",
    "\n",
    "\n",
    "    plt.tight_layout()\n",
    "\n",
    "\n",
    "    comparison_path = os.path.join(\n",
    "        OUTPUT_DIR_L15,\n",
    "\n",
    "        f\"{number:02d}_\"\n",
    "        f\"{base_name}_\"\n",
    "        f\"comparison.png\"\n",
    "    )\n",
    "\n",
    "\n",
    "    plt.savefig(\n",
    "        comparison_path,\n",
    "        dpi=300,\n",
    "        bbox_inches=\"tight\"\n",
    "    )\n",
    "\n",
    "\n",
    "    plt.close(fig)\n",
    "\n",
    "\n",
    "    generated_layer15.append(\n",
    "        comparison_path\n",
    "    )\n",
    "\n",
    "\n",
    "    print(\n",
    "        \"Saved:\",\n",
    "        cam_path\n",
