    "# ============================================================\n",
    "# YOLOv5m + YOLOv8m\n",
    "# SUMMARY FIGURES - SAME SIZE / TIMES NEW ROMAN 8 PT\n",
    "# ============================================================\n",
    "\n",
    "import os\n",
    "import matplotlib.pyplot as plt\n",
    "from matplotlib import font_manager\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 1. FONT CONFIGURATION\n",
    "# ============================================================\n",
    "\n",
    "FONT_PATH = \"/content/times.ttf\"\n",
    "\n",
    "if os.path.exists(FONT_PATH):\n",
    "    font_manager.fontManager.addfont(FONT_PATH)\n",
    "    font_name = font_manager.FontProperties(\n",
    "        fname=FONT_PATH\n",
    "    ).get_name()\n",
    "else:\n",
    "    # Fallback only if Times font file is unavailable\n",
    "    font_name = \"Times New Roman\"\n",
    "\n",
    "plt.rcParams.update({\n",
    "    \"font.family\": font_name,\n",
    "    \"font.size\": 8,\n",
    "    \"axes.titlesize\": 8,\n",
    "    \"axes.labelsize\": 8,\n",
    "    \"xtick.labelsize\": 8,\n",
    "    \"ytick.labelsize\": 8,\n",
    "    \"legend.fontsize\": 8,\n",
    "    \"figure.titlesize\": 8\n",
    "})\n",
    "\n",
    "plt.close(\"all\")\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 2. COMMON FIGURE SETTINGS\n",
    "# ============================================================\n",
    "\n",
    "FIGSIZE = (7.0, 3.65)\n",
    "\n",
    "V5_PNG = \"/content/YOLOv5m_GradCAM_8images_TNR8.png\"\n",
    "V5_PDF = \"/content/YOLOv5m_GradCAM_8images_TNR8.pdf\"\n",
    "\n",
    "V8_PNG = \"/content/YOLOv8m_GradCAM_8images_TNR8.png\"\n",
    "V8_PDF = \"/content/YOLOv8m_GradCAM_8images_TNR8.pdf\"\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 3. FUNCTION TO CREATE IDENTICAL SUMMARY FIGURES\n",
    "# ============================================================\n",
    "\n",
    "def create_summary_figure(results, model_name, png_path, pdf_path):\n",
    "\n",
    "    if len(results) != 8:\n",
    "        raise ValueError(\n",
    "            f\"{model_name}: expected 8 results, \"\n",
    "            f\"but found {len(results)}.\"\n",
    "        )\n",
    "\n",
    "    fig, axes = plt.subplots(\n",
