    "\n",
    "        axes[i].imshow(\n",
    "            result[\"gradcam\"]\n",
    "        )\n",
    "\n",
    "        axes[i].set_title(\n",
    "            f'({chr(97+i)}) '\n",
    "            f'{result[\"class_name\"]}',\n",
    "            fontsize=8,\n",
    "            pad=2\n",
    "        )\n",
    "\n",
    "        axes[i].axis(\"off\")\n",
    "\n",
    "    # Same spacing for both models\n",
    "    plt.subplots_adjust(\n",
