    "        right=0.99,\n",
    "        top=0.95,\n",
    "        bottom=0.02,\n",
    "        wspace=0.03,\n",
    "        hspace=0.12\n",
    "    )\n",
    "\n",
    "    # PNG - 600 dpi\n",
    "    fig.savefig(\n",
    "        png_path,\n",
    "        dpi=600,\n",
    "        bbox_inches=\"tight\",\n",
    "        pad_inches=0.02\n",
    "    )\n",
    "\n",
    "    # Vector PDF\n",
    "    fig.savefig(\n",
    "        pdf_path,\n",
    "        format=\"pdf\",\n",
    "        bbox_inches=\"tight\",\n",
    "        pad_inches=0.02\n",
    "    )\n",
    "\n",
    "    plt.show()\n",
    "    plt.close(fig)\n",
    "\n",
    "    print(f\"\\n{model_name}\")\n",
    "    print(\"PNG:\", png_path)\n",
    "    print(\"PDF:\", pdf_path)\n",
    "\n",
