    "# ============================================================\n",
    "# FINAL FIGURE 6\n",
    "# Original | YOLOv5m Grad-CAM | YOLOv8m Grad-CAM\n",
    "# 4 rows x 3 columns\n",
    "# Times New Roman - 8 pt\n",
    "# IJACSA double-column format\n",
    "# ============================================================\n",
    "\n",
    "import os\n",
    "import matplotlib.pyplot as plt\n",
    "from matplotlib import font_manager\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 1. FONT CONFIGURATION\n",
    "# ============================================================\n",
    "\n",
    "FONT_PATH = \"/content/times.ttf\"\n",
    "\n",
    "if os.path.exists(FONT_PATH):\n",
    "\n",
    "    font_manager.fontManager.addfont(\n",
    "        FONT_PATH\n",
    "    )\n",
    "\n",
    "    FONT_NAME = (\n",
    "        font_manager\n",
    "        .FontProperties(fname=FONT_PATH)\n",
    "        .get_name()\n",
    "    )\n",
    "\n",
    "else:\n",
    "\n",
    "    FONT_NAME = \"Times New Roman\"\n",
    "\n",
    "\n",
    "plt.rcParams.update({\n",
    "    \"font.family\": FONT_NAME,\n",
    "    \"font.size\": 8,\n",
    "    \"axes.titlesize\": 8,\n",
    "    \"figure.titlesize\": 8\n",
    "})\n",
    "\n",
    "plt.close(\"all\")\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 2. SELECT THE FINAL 4 EXAMPLES\n",
    "#\n",
    "# IMPORTANT:\n",
    "# Replace these numbers after visually checking the 8 examples.\n",
    "#\n",
    "# They must represent:\n",
    "# - Glass\n",
    "# - Paper\n",
    "# - Plastic\n",
    "# - Waste\n",
    "#\n",
    "# AND:\n",
    "# - 2 controlled white-background\n",
    "# - 2 visually complex in-store\n",
    "# ============================================================\n",
    "\n",
    "FINAL_NUMBERS = [\n",
    "    1,\n",
    "    2,\n",
    "    3,\n",
    "    4\n",
    "]\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 3. CREATE LOOKUP TABLES\n",
    "# ============================================================\n",
    "\n",
    "v5_lookup = {\n",
    "    result[\"number\"]: result\n",
    "    for result in gradcam_v5_results\n",
    "}\n",
    "\n",
    "v8_lookup = {\n",
    "    result[\"number\"]: result\n",
    "    for result in gradcam_v8_results\n",
    "}\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 4. VERIFY THAT THE SAME IMAGES EXIST\n",
    "# IN BOTH MODEL RESULTS\n",
    "# ============================================================\n",
    "\n",
    "for number in FINAL_NUMBERS:\n",
    "\n",
    "    if number not in v5_lookup:\n",
    "        raise ValueError(\n",
    "            f\"Example {number} is missing \"\n",
    "            f\"from YOLOv5 results.\"\n",
    "        )\n",
    "\n",
    "    if number not in v8_lookup:\n",
    "        raise ValueError(\n",
    "            f\"Example {number} is missing \"\n",
    "            f\"from YOLOv8 results.\"\n",
    "        )\n",
    "\n",
    "    v5_name = os.path.basename(\n",
    "        v5_lookup[number][\"image_path\"]\n",
    "    )\n",
    "\n",
    "    v8_name = os.path.basename(\n",
    "        v8_lookup[number][\"image_path\"]\n",
    "    )\n",
    "\n",
    "    if v5_name != v8_name:\n",
    "\n",
    "        raise ValueError(\n",
    "            f\"Image mismatch for example {number}:\\n\"\n",
    "            f\"YOLOv5: {v5_name}\\n\"\n",
    "            f\"YOLOv8: {v8_name}\"\n",
    "        )\n",
    "\n",
    "\n",
    "print(\n",
    "    \"All selected images match \"\n",
    "    \"between YOLOv5m and YOLOv8m.\"\n",
    ")\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 5. OUTPUT PATHS\n",
    "# ============================================================\n",
    "\n",
    "FINAL_PNG = (\n",
    "    \"/content/\"\n",
    "    \"Fig6_GradCAM_Final_IJACSA.png\"\n",
    ")\n",
    "\n",
    "FINAL_PDF = (\n",
    "    \"/content/\"\n",
    "    \"Fig6_GradCAM_Final_IJACSA.pdf\"\n",
    ")\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 6. CREATE FIGURE\n",
    "# ============================================================\n",
    "\n",
