    "# ============================================================\n",
    "# FINAL FIGURE 6\n",
    "# Original | YOLOv5m Grad-CAM | YOLOv8m Grad-CAM\n",
    "# 4 rows x 3 columns\n",
    "# Times New Roman - 8 pt\n",
    "# IJACSA double-column format\n",
    "# ============================================================\n",
    "\n",
    "import os\n",
    "import matplotlib.pyplot as plt\n",
    "from matplotlib import font_manager\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 1. FONT CONFIGURATION\n",
    "# ============================================================\n",
    "\n",
    "FONT_PATH = \"/content/times.ttf\"\n",
    "\n",
    "if os.path.exists(FONT_PATH):\n",
    "\n",
    "    font_manager.fontManager.addfont(\n",
    "        FONT_PATH\n",
    "    )\n",
    "\n",
    "    FONT_NAME = (\n",
    "        font_manager\n",
    "        .FontProperties(fname=FONT_PATH)\n",
    "        .get_name()\n",
    "    )\n",
    "\n",
    "else:\n",
    "\n",
    "    FONT_NAME = \"Times New Roman\"\n",
    "\n",
    "\n",
    "plt.rcParams.update({\n",
    "    \"font.family\": FONT_NAME,\n",
    "    \"font.size\": 8,\n",
    "    \"axes.titlesize\": 8,\n",
    "    \"figure.titlesize\": 8\n",
    "})\n",
    "\n",
    "plt.close(\"all\")\n",
    "\n",
    "\n",
