    "#\n",
    "# They must represent:\n",
    "# - Glass\n",
    "# - Paper\n",
    "# - Plastic\n",
    "# - Waste\n",
    "#\n",
    "# AND:\n",
    "# - 2 controlled white-background\n",
    "# - 2 visually complex in-store\n",
    "# ============================================================\n",
    "\n",
    "FINAL_NUMBERS = [\n",
    "    1,\n",
    "    2,\n",
    "    3,\n",
    "    4\n",
    "]\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 3. CREATE LOOKUP TABLES\n",
    "# ============================================================\n",
    "\n",
    "v5_lookup = {\n",
    "    result[\"number\"]: result\n",
    "    for result in gradcam_v5_results\n",
    "}\n",
    "\n",
    "v8_lookup = {\n",
    "    result[\"number\"]: result\n",
    "    for result in gradcam_v8_results\n",
    "}\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 4. VERIFY THAT THE SAME IMAGES EXIST\n",
    "# IN BOTH MODEL RESULTS\n",
    "# ============================================================\n",
    "\n",
    "for number in FINAL_NUMBERS:\n",
    "\n",
    "    if number not in v5_lookup:\n",
    "        raise ValueError(\n",
    "            f\"Example {number} is missing \"\n",
    "            f\"from YOLOv5 results.\"\n",
    "        )\n",
    "\n",
    "    if number not in v8_lookup:\n",
    "        raise ValueError(\n",
    "            f\"Example {number} is missing \"\n",
    "            f\"from YOLOv8 results.\"\n",
    "        )\n",
    "\n",
    "    v5_name = os.path.basename(\n",
    "        v5_lookup[number][\"image_path\"]\n",
    "    )\n",
    "\n",
    "    v8_name = os.path.basename(\n",
    "        v8_lookup[number][\"image_path\"]\n",
    "    )\n",
    "\n",
    "    if v5_name != v8_name:\n",
    "\n",
    "        raise ValueError(\n",
    "            f\"Image mismatch for example {number}:\\n\"\n",
    "            f\"YOLOv5: {v5_name}\\n\"\n",
    "            f\"YOLOv8: {v8_name}\"\n",
    "        )\n",
    "\n",
    "\n",
    "print(\n",
