    ")\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 5. OUTPUT PATHS\n",
    "# ============================================================\n",
    "\n",
    "FINAL_PNG = (\n",
    "    \"/content/\"\n",
    "    \"Fig6_GradCAM_Final_IJACSA.png\"\n",
    ")\n",
    "\n",
    "FINAL_PDF = (\n",
    "    \"/content/\"\n",
    "    \"Fig6_GradCAM_Final_IJACSA.pdf\"\n",
    ")\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 6. CREATE FIGURE\n",
    "# ============================================================\n",
    "\n",
    "# Double-column width\n",
    "FIG_WIDTH = 7.0\n",
    "\n",
    "# Similar vertical proportion to reference figure\n",
    "FIG_HEIGHT = 8.0\n",
    "\n",
    "\n",
    "fig, axes = plt.subplots(\n",
    "    nrows=4,\n",
    "    ncols=3,\n",
    "    figsize=(FIG_WIDTH, FIG_HEIGHT)\n",
    ")\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 7. COLUMN HEADERS\n",
    "# ============================================================\n",
    "\n",
    "column_titles = [\n",
    "    \"Original\",\n",
    "    \"YOLOv5m Grad-CAM\",\n",
    "    \"YOLOv8m Grad-CAM\"\n",
    "]\n",
    "\n",
    "\n",
    "for col, title in enumerate(\n",
    "    column_titles\n",
    "):\n",
    "\n",
    "    axes[0, col].set_title(\n",
    "        title,\n",
    "        fontsize=8,\n",
    "        fontweight=\"bold\",\n",
    "        pad=5\n",
    "    )\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 8. ADD THE FOUR EXAMPLES\n",
    "# ============================================================\n",
    "\n",
    "row_labels = [\n",
