    "    \"(b)\",\n",
    "    \"(c)\",\n",
    "    \"(d)\"\n",
    "]\n",
    "\n",
    "\n",
    "for row, number in enumerate(\n",
    "    FINAL_NUMBERS\n",
    "):\n",
    "\n",
    "    v5 = v5_lookup[number]\n",
    "    v8 = v8_lookup[number]\n",
    "\n",
    "\n",
    "    # --------------------------------------------------------\n",
    "    # ORIGINAL\n",
    "    # --------------------------------------------------------\n",
    "\n",
    "    axes[row, 0].imshow(\n",
    "        v5[\"original\"]\n",
    "    )\n",
    "\n",
    "    axes[row, 0].axis(\n",
    "        \"off\"\n",
    "    )\n",
    "\n",
    "\n",
    "    # --------------------------------------------------------\n",
    "    # YOLOv5m GRAD-CAM\n",
    "    # --------------------------------------------------------\n",
    "\n",
    "    axes[row, 1].imshow(\n",
    "        v5[\"gradcam\"]\n",
    "    )\n",
    "\n",
    "    axes[row, 1].axis(\n",
    "        \"off\"\n",
    "    )\n",
    "\n",
    "\n",
    "    # --------------------------------------------------------\n",
    "    # YOLOv8m GRAD-CAM\n",
    "    # --------------------------------------------------------\n",
    "\n",
    "    axes[row, 2].imshow(\n",
    "        v8[\"gradcam\"]\n",
    "    )\n",
    "\n",
    "    axes[row, 2].axis(\n",
    "        \"off\"\n",
    "    )\n",
    "\n",
    "\n",
    "    # --------------------------------------------------------\n",
    "    # ROW LABEL: (a), (b), (c), (d)\n",
    "    # --------------------------------------------------------\n",
    "\n",
    "    axes[row, 0].text(\n",
    "        -0.08,\n",
    "        0.98,\n",
    "        row_labels[row],\n",
    "        transform=axes[row, 0].transAxes,\n",
    "        fontsize=8,\n",
    "        fontweight=\"bold\",\n",
    "        va=\"top\",\n",
    "        ha=\"right\"\n",
    "    )\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 9. SPACING\n",
    "# ============================================================\n",
    "\n",
    "plt.subplots_adjust(\n",
    "    left=0.055,\n",
    "    right=0.995,\n",
    "    top=0.965,\n",
    "    bottom=0.015,\n",
    "    wspace=0.055,\n",
    "    hspace=0.075\n",
    ")\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 10. SAVE PNG - 600 DPI\n",
    "# ============================================================\n",
    "\n",
    "fig.savefig(\n",
    "    FINAL_PNG,\n",
    "    dpi=600,\n",
    "    bbox_inches=\"tight\",\n",
    "    pad_inches=0.02\n",
    ")\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 11. SAVE VECTOR PDF\n",
    "# ============================================================\n",
    "\n",
    "fig.savefig(\n",
    "    FINAL_PDF,\n",
    "    format=\"pdf\",\n",
    "    bbox_inches=\"tight\",\n",
    "    pad_inches=0.02\n",
    ")\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 12. DISPLAY\n",
    "# ============================================================\n",
    "\n",
    "plt.show()\n",
    "\n",
    "plt.close(fig)\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 13. SUMMARY\n",
    "# ============================================================\n",
    "\n",
    "print(\"\\n\" + \"=\" * 70)\n",
    "\n",
    "print(\n",
    "    \"FINAL FIGURE 6 COMPLETED\"\n",
    ")\n",
    "\n",
    "print(\"=\" * 70)\n",
    "\n",
    "print(\n",
