  {
   "cell_type": "code",
   "execution_count": null,
   "metadata": {},
   "outputs": [],
   "source": [
    "# ============================================================\n",
    "# YOLOv5m RUN 4\n",
    "# GRAD-CAM TARGET-LAYER VERIFICATION\n",
    "# Same images / same class-conditioned criterion\n",
    "# ============================================================\n",
    "\n",
    "# If needed:\n",
    "# !pip install -q grad-cam\n",
    "\n",
    "import os\n",
    "import sys\n",
    "import glob\n",
    "import cv2\n",
    "import torch\n",
    "import torch.nn as nn\n",
    "import numpy as np\n",
    "import matplotlib.pyplot as plt\n",
    "\n",
    "from pytorch_grad_cam import GradCAM\n",
    "from pytorch_grad_cam.utils.image import show_cam_on_image\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 1. CONFIGURATION\n",
    "# ============================================================\n",
    "\n",
    "DEVICE = torch.device(\"cuda\" if torch.cuda.is_available() else \"cpu\")\n",
    "\n",
    "YOLOV5_DIR = \"/content/yolov5\"\n",
    "TEST_DIR = \"/content/dataset/test/images\"\n",
    "\n",
    "IMG_SIZE = 640\n",
    "CONF_THRES = 0.25\n",
    "IOU_THRES = 0.60\n",
    "\n",
    "print(\"=\" * 70)\n",
    "print(\"YOLOv5m RUN 4 - GRAD-CAM VERIFICATION\")\n",
    "print(\"=\" * 70)\n",
    "print(\"Device:\", DEVICE)\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 2. YOLOv5 REPOSITORY\n",
    "# ============================================================\n",
    "\n",
    "if not os.path.exists(YOLOV5_DIR):\n",
    "    raise FileNotFoundError(\n",
    "        \"/content/yolov5 was not found.\"\n",
    "    )\n",
    "\n",
    "if YOLOV5_DIR not in sys.path:\n",
    "    sys.path.insert(0, YOLOV5_DIR)\n",
    "\n",
    "from models.common import DetectMultiBackend\n",
    "from utils.general import non_max_suppression\n",
    "from utils.augmentations import letterbox\n",
    "from utils.torch_utils import select_device\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 3. FIND YOLOv5m RUN 4 WEIGHTS\n",
    "# ============================================================\n",
    "\n",
    "matches = glob.glob(\n",
    "    \"/content/**/best_v5m_4.pt\",\n",
    "    recursive=True\n",
    ")\n",
    "\n",
    "if len(matches) == 0:\n",
    "    raise FileNotFoundError(\n",
    "        \"best_v5m_4.pt was not found.\"\n",
    "    )\n",
    "\n",
    "WEIGHT_PATH = matches[0]\n",
    "\n",
    "print(\"\\nWeights:\")\n",
    "print(WEIGHT_PATH)\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 4. LOAD YOLOv5\n",
    "# ============================================================\n",
    "\n",
    "device_v5 = select_device(\n",
    "    \"0\" if torch.cuda.is_available() else \"cpu\"\n",
    ")\n",
    "\n",
    "backend = DetectMultiBackend(\n",
    "    WEIGHT_PATH,\n",
    "    device=device_v5,\n",
    "    dnn=False,\n",
    "    data=None,\n",
    "    fp16=False\n",
    ")\n",
    "\n",
    "# Underlying PyTorch YOLOv5 model\n",
    "model_v5 = backend.model\n",
    "\n",
    "model_v5.to(DEVICE)\n",
    "model_v5.float()\n",
    "model_v5.eval()\n",
    "\n",
    "torch.set_grad_enabled(True)\n",
    "\n",
    "for p in model_v5.parameters():\n",
    "    p.requires_grad_(True)\n",
    "\n",
    "CLASS_NAMES_V5 = backend.names\n",
    "\n",
    "print(\"\\nClasses:\")\n",
    "print(CLASS_NAMES_V5)\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 5. INSPECT MODEL STRUCTURE\n",
    "# ============================================================\n",
    "\n",
    "print(\"\\nYOLOv5 model layers:\")\n",
    "print(\"-\" * 70)\n",
    "\n",
    "for i, layer in enumerate(model_v5.model):\n",
    "    print(\n",
    "        f\"{i:2d} | \"\n",
    "        f\"{type(layer).__name__}\"\n",
    "    )\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 6. TEST IMAGES - SAME SELECTION AS YOLOv8\n",
    "# ============================================================\n",
    "\n",
    "extensions = [\n",
    "    \"*.jpg\",\n",
    "    \"*.jpeg\",\n",
    "    \"*.png\",\n",
    "    \"*.JPG\",\n",
    "    \"*.JPEG\",\n",
    "    \"*.PNG\"\n",
    "]\n",
    "\n",
    "image_paths = []\n",
    "\n",
    "for ext in extensions:\n",
    "    image_paths.extend(\n",
    "        glob.glob(\n",
    "            os.path.join(TEST_DIR, ext)\n",
    "        )\n",
    "    )\n",
    "\n",
    "image_paths = sorted(image_paths)\n",
    "\n",
    "if len(image_paths) == 0:\n",
    "    raise FileNotFoundError(\n",
    "        \"No test images found.\"\n",
    "    )\n",
    "\n",
    "indices = np.linspace(\n",
    "    0,\n",
    "    len(image_paths) - 1,\n",
    "    8,\n",
    "    dtype=int\n",
    ")\n",
    "\n",
    "selected_images_v5 = [\n",
    "    image_paths[i]\n",
    "    for i in indices\n",
    "]\n",
    "\n",
    "print(\"\\nTest images:\", len(image_paths))\n",
    "\n",
    "print(\"\\nSelected images:\")\n",
    "\n",
    "for i, p in enumerate(\n",
    "    selected_images_v5,\n",
    "    start=1\n",
    "):\n",
    "    print(i, os.path.basename(p))\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 7. PREPROCESSING\n",
    "# ============================================================\n",
    "#\n",
    "# YOLOv5 native letterbox preprocessing.\n",
    "# Dataset images are already 640x640, but this keeps the\n",
    "# procedure consistent with the YOLOv5 inference pipeline.\n",
    "#\n",
    "# ============================================================\n",
    "\n",
    "def prepare_v5_image(image_path):\n",
    "\n",
    "    img0 = cv2.imread(image_path)\n",
    "\n",
    "    if img0 is None:\n",
    "        raise ValueError(\n",
    "            f\"Could not read {image_path}\"\n",
    "        )\n",
    "\n",
    "    # YOLOv5 letterbox\n",
    "    img = letterbox(\n",
    "        img0,\n",
    "        new_shape=IMG_SIZE,\n",
    "        stride=32,\n",
    "        auto=False\n",
    "    )[0]\n",
    "\n",
    "    # BGR -> RGB\n",
    "    img_rgb = cv2.cvtColor(\n",
    "        img,\n",
    "        cv2.COLOR_BGR2RGB\n",
    "    )\n",
    "\n",
    "    img_float = (\n",
    "        img_rgb.astype(np.float32) / 255.0\n",
    "    )\n",
    "\n",
    "    tensor = torch.from_numpy(\n",
    "        img_float\n",
    "    ).permute(\n",
    "        2, 0, 1\n",
    "    ).unsqueeze(0)\n",
    "\n",
    "    tensor = tensor.to(\n",
    "        DEVICE,\n",
    "        dtype=torch.float32\n",
    "    )\n",
    "\n",
    "    tensor.requires_grad_(True)\n",
    "\n",
    "    original_rgb = cv2.cvtColor(\n",
    "        img0,\n",
    "        cv2.COLOR_BGR2RGB\n",
    "    )\n",
    "\n",
    "    return (\n",
    "        original_rgb,\n",
    "        img_float,\n",
    "        tensor\n",
    "    )\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 8. YOLOv5 GRAD-CAM WRAPPER\n",
    "# ============================================================\n",
    "#\n",
    "# YOLOv5 Detect output in inference mode is normally:\n",
    "#\n",
    "# prediction shape:\n",
    "# [B, N, 5 + nc]\n",
    "#\n",
    "# channels:\n",
    "# 0:4 -> box\n",
    "# 4   -> objectness\n",
    "# 5:  -> class probabilities\n",
    "#\n",
    "# For Grad-CAM we retain a differentiable class response:\n",
    "#\n",
    "# objectness * class probability\n",
    "#\n",
    "# Output:\n",
    "# [B, nc, N]\n",
    "#\n",
    "# ============================================================\n",
    "\n",
    "class YOLOv5GradCAMWrapper(nn.Module):\n",
    "\n",
    "    def __init__(self, detector):\n",
    "        super().__init__()\n",
    "        self.detector = detector\n",
    "\n",
    "    def forward(self, x):\n",
    "\n",
    "        with torch.enable_grad():\n",
    "\n",
    "            output = self.detector(x)\n",
    "\n",
    "            if isinstance(output, tuple):\n",
    "                predictions = output[0]\n",
    "\n",
    "            elif isinstance(output, list):\n",
    "                predictions = output[0]\n",
    "\n",
    "            else:\n",
    "                predictions = output\n",
    "\n",
    "            if predictions.ndim != 3:\n",
    "                raise RuntimeError(\n",
    "                    f\"Unexpected YOLOv5 output shape: \"\n",
    "                    f\"{predictions.shape}\"\n",
    "                )\n",
    "\n",
    "            objectness = predictions[:, :, 4:5]\n",
    "\n",
    "            class_probabilities = predictions[:, :, 5:]\n",
    "\n",
    "            class_scores = (\n",
    "                objectness *\n",
    "                class_probabilities\n",
    "            )\n",
    "\n",
    "            # [B, N, nc] -> [B, nc, N]\n",
    "            class_scores = class_scores.permute(\n",
    "                0, 2, 1\n",
    "            )\n",
    "\n",
    "            return class_scores\n",
    "\n",
    "\n",
    "wrapped_v5 = YOLOv5GradCAMWrapper(\n",
    "    model_v5\n",
    ")\n",
    "\n",
    "wrapped_v5.to(DEVICE)\n",
    "wrapped_v5.eval()\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 9. GRAD-CAM TARGET\n",
    "# ============================================================\n",
    "\n",
    "class YOLOv5ClassTarget:\n",
    "\n",
    "    def __init__(self, class_id):\n",
    "        self.class_id = int(class_id)\n",
    "\n",
    "    def __call__(self, model_output):\n",
    "\n",
    "        class_response = model_output[\n",
    "            self.class_id, :\n",
    "        ]\n",
    "\n",
    "        return class_response.max()\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 10. STANDARD YOLOv5 DETECTION\n",
    "# ============================================================\n",
    "\n",
    "def get_main_detection_v5(\n",
    "    image_path\n",
    "):\n",
    "\n",
    "    _, _, tensor = prepare_v5_image(\n",
    "        image_path\n",
    "    )\n",
    "\n",
    "    # Standard inference doesn't need gradients\n",
    "    with torch.no_grad():\n",
    "\n",
    "        prediction = backend(\n",
    "            tensor,\n",
    "            augment=False,\n",
    "            visualize=False\n",
    "        )\n",
    "\n",
    "        prediction = non_max_suppression(\n",
    "            prediction,\n",
    "            conf_thres=CONF_THRES,\n",
    "            iou_thres=IOU_THRES,\n",
    "            classes=None,\n",
    "            agnostic=False,\n",
    "            max_det=300\n",
    "        )\n",
    "\n",
    "    detections = prediction[0]\n",
    "\n",
    "    if detections is None or len(detections) == 0:\n",
    "        return None\n",
    "\n",
    "    # NMS output:\n",
    "    # x1, y1, x2, y2, confidence, class\n",
    "\n",
    "    best_index = torch.argmax(\n",
    "        detections[:, 4]\n",
    "    )\n",
    "\n",
    "    best = detections[\n",
    "        best_index\n",
    "    ]\n",
    "\n",
    "    class_id = int(\n",
    "        best[5].item()\n",
    "    )\n",
    "\n",
    "    confidence = float(\n",
    "        best[4].item()\n",
    "    )\n",
    "\n",
    "    bbox = (\n",
    "        best[:4]\n",
    "        .detach()\n",
    "        .cpu()\n",
    "        .numpy()\n",
    "    )\n",
    "\n",
    "    return (\n",
    "        class_id,\n",
    "        confidence,\n",
    "        bbox\n",
    "    )\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 11. VERIFY GRADIENT GRAPH\n",
    "# ============================================================\n",
    "\n",
    "test_image = selected_images_v5[0]\n",
    "\n",
    "_, _, test_tensor = prepare_v5_image(\n",
    "    test_image\n",
    ")\n",
    "\n",
    "test_output = wrapped_v5(\n",
    "    test_tensor\n",
    ")\n",
    "\n",
    "print(\"\\n\" + \"=\" * 70)\n",
    "print(\"GRADIENT CHECK\")\n",
    "print(\"=\" * 70)\n",
    "\n",
    "print(\n",
    "    \"Wrapper output shape:\",\n",
    "    test_output.shape\n",
    ")\n",
    "\n",
    "print(\n",
    "    \"requires_grad:\",\n",
    "    test_output.requires_grad\n",
    ")\n",
    "\n",
    "print(\n",
    "    \"grad_fn:\",\n",
    "    test_output.grad_fn\n",
    ")\n",
    "\n",
    "if not test_output.requires_grad:\n",
    "    raise RuntimeError(\n",
    "        \"YOLOv5 output has no gradient graph.\"\n",
    "    )\n",
    "\n",
    "print(\"Gradient graph: OK\")\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 12. GET DETECTION FOR FIRST IMAGE\n",
    "# ============================================================\n",
    "\n",
    "main_detection = get_main_detection_v5(\n",
    "    test_image\n",
    ")\n",
    "\n",
    "if main_detection is None:\n",
    "    raise RuntimeError(\n",
    "        \"No detection on first test image.\"\n",
    "    )\n",
    "\n",
    "class_id, confidence, bbox = (\n",
    "    main_detection\n",
    ")\n",
    "\n",
    "class_name = CLASS_NAMES_V5[\n",
    "    class_id\n",
    "]\n",
    "\n",
    "print(\"\\nImage:\")\n",
    "print(os.path.basename(test_image))\n",
    "\n",
    "print(\n",
    "    f\"Selected detection: \"\n",
    "    f\"{class_name} | \"\n",
    "    f\"confidence={confidence:.3f}\"\n",
    ")\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 13. CANDIDATE DEEP LAYERS\n",
    "# ============================================================\n",
    "#\n",
    "# YOLOv5m normally ends with:\n",
    "#\n",
    "# ... C3\n",
    "# ... Conv\n",
    "# ... Concat\n",
    "# ... C3\n",
    "# Detect\n",
    "#\n",
    "# We inspect three deep feature layers.\n",
    "#\n",
    "# IMPORTANT:\n",
    "# The exact printed architecture above is the authoritative\n",
    "# reference. We do not assume these are equivalent to\n",
    "# YOLOv8 layer indices.\n",
    "#\n",
    "# ============================================================\n",
    "\n",
    "num_layers = len(model_v5.model)\n",
    "\n",
    "print(\"\\nNumber of YOLOv5 layers:\", num_layers)\n",
    "\n",
    "print(\"\\nLast layers:\")\n",
    "\n",
    "for i in range(\n",
    "    max(0, num_layers - 8),\n",
    "    num_layers\n",
    "):\n",
    "    print(\n",
    "        i,\n",
    "        type(model_v5.model[i]).__name__\n",
    "    )\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 14. AUTOMATICALLY CHOOSE THREE DEEP CONV/C3 FEATURES\n",
    "# ============================================================\n",
    "#\n",
    "# For C3 modules, use their final cv3 convolution.\n",
    "# For Conv modules, use their internal Conv2d.\n",
    "#\n",
    "# ============================================================\n",
    "\n",
    "candidate_layers = {}\n",
    "\n",
    "for i in range(\n",
    "    num_layers - 2,\n",
    "    max(-1, num_layers - 12),\n",
    "    -1\n",
    "):\n",
    "\n",
    "    layer = model_v5.model[i]\n",
    "\n",
    "    # C3\n",
    "    if hasattr(layer, \"cv3\") and hasattr(\n",
    "        layer.cv3,\n",
    "        \"conv\"\n",
    "    ):\n",
    "\n",
    "        candidate_layers[\n",
    "            f\"Layer {i} - \"\n",
    "            f\"{type(layer).__name__}\"\n",
    "        ] = layer.cv3.conv\n",
    "\n",
    "    # Standard YOLOv5 Conv\n",
    "    elif hasattr(layer, \"conv\") and isinstance(\n",
    "        layer.conv,\n",
    "        nn.Conv2d\n",
    "    ):\n",
    "\n",
    "        candidate_layers[\n",
    "            f\"Layer {i} - \"\n",
    "            f\"{type(layer).__name__}\"\n",
    "        ] = layer.conv\n",
    "\n",
    "    if len(candidate_layers) == 3:\n",
    "        break\n",
    "\n",
    "\n",
    "if len(candidate_layers) < 3:\n",
    "\n",
    "    raise RuntimeError(\n",
    "        \"Could not automatically find \"\n",
    "        \"three candidate layers. \"\n",
    "        \"Check the printed architecture.\"\n",
    "    )\n",
    "\n",
    "\n",
    "print(\"\\nCandidate Grad-CAM layers:\")\n",
    "\n",
    "for name, layer in candidate_layers.items():\n",
    "\n",
    "    print(\"\\n\", name)\n",
    "    print(layer)\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 15. COMPARE TARGET LAYERS\n",
    "# ============================================================\n",
    "\n",
    "targets = [\n",
    "    YOLOv5ClassTarget(\n",
    "        class_id\n",
    "    )\n",
    "]\n",
    "\n",
    "cam_results = {}\n",
    "\n",
    "for layer_name, layer in candidate_layers.items():\n",
    "\n",
    "    print(\"\\n\" + \"-\" * 70)\n",
    "    print(\"Processing:\", layer_name)\n",
    "\n",
    "    (\n",
    "        original_rgb,\n",
    "        input_rgb,\n",
    "        tensor\n",
    "    ) = prepare_v5_image(\n",
    "        test_image\n",
    "    )\n",
    "\n",
    "    wrapped_v5.zero_grad(\n",
    "        set_to_none=True\n",
    "    )\n",
    "\n",
    "    cam = GradCAM(\n",
    "        model=wrapped_v5,\n",
    "        target_layers=[layer]\n",
    "    )\n",
    "\n",
    "    grayscale_cam = cam(\n",
    "        input_tensor=tensor,\n",
    "        targets=targets\n",
    "    )[0]\n",
    "\n",
    "    overlay = show_cam_on_image(\n",
    "        input_rgb,\n",
    "        grayscale_cam,\n",
    "        use_rgb=True\n",
    "    )\n",
    "\n",
    "    cam_results[\n",
    "        layer_name\n",
    "    ] = overlay\n",
    "\n",
    "    print(\n",
    "        \"CAM range:\",\n",
    "        float(grayscale_cam.min()),\n",
    "        \"to\",\n",
    "        float(grayscale_cam.max())\n",
    "    )\n",
    "\n",
    "    cam.activations_and_grads.release()\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 16. DISPLAY COMPARISON\n",
    "# ============================================================\n",
    "\n",
    "fig, axes = plt.subplots(\n",
    "    1,\n",
    "    4,\n",
    "    figsize=(20, 5)\n",
    ")\n",
    "\n",
    "axes[0].imshow(\n",
    "    original_rgb\n",
    ")\n",
    "\n",
    "axes[0].set_title(\n",
    "    \"Original\"\n",
    ")\n",
    "\n",
    "axes[0].axis(\"off\")\n",
    "\n",
    "\n",
    "for ax, (\n",
    "    name,\n",
    "    overlay\n",
    ") in zip(\n",
    "    axes[1:],\n",
    "    cam_results.items()\n",
    "):\n",
    "\n",
    "    ax.imshow(\n",
    "        overlay\n",
    "    )\n",
    "\n",
    "    ax.set_title(\n",
    "        name\n",
    "    )\n",
    "\n",
    "    ax.axis(\"off\")\n",
    "\n",
    "\n",
    "plt.suptitle(\n",
    "    f\"YOLOv5m Grad-CAM Layer Comparison\\n\"\n",
    "    f\"Target: {class_name} \"\n",
    "    f\"(confidence={confidence:.2f})\",\n",
    "    fontsize=14\n",
    ")\n",
    "\n",
    "plt.tight_layout()\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 17. SAVE\n",
    "# ============================================================\n",
    "\n",
    "OUTPUT_PATH = (\n",
    "    \"/content/\"\n",
    "    \"YOLOv5m_GradCAM_Layer_Comparison.png\"\n",
    ")\n",
    "\n",
    "plt.savefig(\n",
    "    OUTPUT_PATH,\n",
    "    dpi=300,\n",
    "    bbox_inches=\"tight\"\n",
    ")\n",
    "\n",
    "plt.show()\n",
    "plt.close(fig)\n",
    "\n",
    "\n",
    "print(\"\\n\" + \"=\" * 70)\n",
    "print(\"YOLOv5m LAYER VERIFICATION COMPLETED\")\n",
    "print(\"=\" * 70)\n",
    "\n",
    "print(\"Saved:\")\n",
    "print(OUTPUT_PATH)"
   ]
  },
