  {
   "cell_type": "code",
   "source": [
    "# ============================================================\n",
    "# YOLOv8m RUN 4 - GRAD-CAM INITIALIZATION\n",
    "# ============================================================\n",
    "\n",
    "import torch\n",
    "import torch.nn as nn\n",
    "import cv2\n",
    "import numpy as np\n",
    "\n",
    "from pytorch_grad_cam import GradCAM\n",
    "from pytorch_grad_cam.utils.image import show_cam_on_image\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 1. GET PYTORCH MODEL\n",
    "# ============================================================\n",
    "\n",
    "model = yolo.model\n",
    "\n",
    "model.eval()\n",
    "\n",
    "device = next(model.parameters()).device\n",
    "\n",
    "print(\"Device:\", device)\n",
    "print(\"Model loaded:\", type(model))\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 2. CLASS NAMES\n",
    "# ============================================================\n",
    "\n",
    "CLASS_NAMES = yolo.names\n",
    "\n",
    "print(\"Classes:\", CLASS_NAMES)\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 3. WRAPPER FOR GRAD-CAM\n",
    "# ============================================================\n",
    "\n",
    "class YOLOv8Wrapper(nn.Module):\n",
    "\n",
    "    def __init__(self, model):\n",
    "        super().__init__()\n",
    "        self.model = model\n",
    "\n",
    "    def forward(self, x):\n",
    "\n",
    "        output = self.model(x)\n",
    "\n",
    "        # Ultralytics detection output\n",
    "        if isinstance(output, (list, tuple)):\n",
    "            output = output[0]\n",
    "\n",
    "        return output\n",
    "\n",
    "\n",
    "wrapped_model = YOLOv8Wrapper(model)\n",
    "\n",
    "wrapped_model.eval()\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 4. CLASS-CONDITIONED GRAD-CAM TARGET\n",
    "# ============================================================\n",
    "\n",
    "class YOLOClassDetectionTarget:\n",
    "\n",
    "    def __init__(self, class_id):\n",
    "        self.class_id = class_id\n",
    "\n",
    "    def __call__(self, model_output):\n",
    "\n",
    "        # YOLOv8 raw output:\n",
    "        # [batch, 4 + num_classes, num_predictions]\n",
    "\n",
    "        if model_output.ndim == 3:\n",
    "            model_output = model_output[0]\n",
    "\n",
    "        # Class scores begin after bbox coordinates\n",
    "        class_scores = model_output[4:, :]\n",
    "\n",
    "        # Maximum raw response for selected class\n",
    "        return class_scores[self.class_id].max()\n",
    "\n",
    "\n",
    "# ============================================================\n",
    "# 5. VERIFY TARGET LAYER\n",
    "# ============================================================\n",
    "\n",
    "TARGET_LAYER = model.model[15].cv2.conv\n",
    "\n",
    "print(\"\\nTarget Layer 15:\")\n",
    "print(TARGET_LAYER)\n",
    "\n",
    "print(\"\\nInitialization completed.\")"
   ],
   "metadata": {},
   "execution_count": null,
   "outputs": []
  },
